const bestsellerBadge = '<span class="elv-editor-pick"><span aria-hidden="true">★</span> Bestseller</span>'+
  '<small class="elv-pick-context">Curated pick · selected for product presentation</small>';

function purchaseBox(box, path) {
  const withoutSeller = box.replace(/<p\b[^>]*>\s*(?:<strong>)?Sold by\s+Elvarins(?:\s*\([^<]*\))?\.?\s*(?:<\/strong>)?\s*<\/p>/gi, '');
  const styled = withoutSeller.replace(/<(p|span)\b([^>]*)>\s*(?:<strong>)?((?:In Stock|Out of Stock|Sold Out)(?:\s*(?:—|&mdash;)\s*Ready to Ship)?)(?:<\/strong>)?\s*<\/\1>/gi,
    (_, tag, attrs, label) => {
      const status = /^in stock/i.test(label) ? 'in' : 'out';
      return '<'+tag+attrs+' data-stock-state="'+status+'">'+label+'</'+tag+'>';
    })
    .replace(/(<strong class="price">)(\d+\.\d{2})(<\/strong>)/, '$1$$$2$3');
  const available = !styled.includes('data-stock-state=') && /<button[^>]*(?:data-elv-cart-add|data-kitchen-action=)/.test(styled);
  const status = available ? '<p class="stock-label" data-stock-state="ready">Available to order</p>' : '';
  const pick = editorPicks.has(path) && /<button[^>]*(?:data-elv-cart-add|data-kitchen-action=)/.test(styled) &&
    !styled.includes('data-stock-state="out"')
    ? bestsellerBadge
    : '';
  return styled.replace(/<p class="kitchen-retail-price"[^>]*>[\s\S]*?<\/p>|<strong class="price"[^>]*>[\s\S]*?<\/strong>|<span class="price"[^>]*>[\s\S]*?<\/span>/,
    price=>price+status+pick);
}

export function polishOffers(html, path) {
  let out = html.replace('/shipping-promo.js?v=2','/shipping-promo.js?v=3').replace(/<aside class="retail-buy-box"[^>]*>[\s\S]*?<\/aside>/g, box=>purchaseBox(box,path));
  if (path==='/') {
    out = out.replace(/<article\b[^>]*>[\s\S]*?<\/article>/g, row=>{
      const product = row.match(/href="(\/products\/[a-z0-9-]+)"/)?.[1];
      if (!editorPicks.has(product) || /data-no-cart|data-stock-state="out"|>\s*Out of Stock\s*</i.test(row)) return row;
      return row.replace(/<\/article>$/,()=>'<div class="elv-card-pick">'+bestsellerBadge+'</div></article>');
    });
  }
  if (path==='/') {
    out = out.replace(/(<dialog class="shipping-promo-dialog"[^>]*>[\s\S]*?<\/form>)[\s\S]*?<\/dialog>/, (_dialog, head)=>head+
      '<img class="elv-offer-photo" src="/media/storefront/shipping-offer-v1.jpg" alt="" width="576" height="264" decoding="async">'+
      '<div class="elv-offer-copy"><span class="elv-offer-kicker">U.S. delivery perk</span>'+
      '<h2 id="shipping-promo-title">Free shipping <span>at $149+</span></h2>'+
      '<p>Fill your cart with favorites across Kitchen, Pets and Collectibles. Standard U.S. shipping is free when your merchandise subtotal reaches $149 before tax.</p>'+
      '<div class="elv-offer-actions"><a class="btn btn-primary" href="/#elv-departments" data-offer-continue>Shop departments <span aria-hidden="true">→</span></a>'+
      '<a href="/shipping-delivery">Shipping details</a></div></div></dialog>');
  }
  return out;
}

