export function offerCloseScript(source) {
  return source.replace("const key = 'elvarins-shipping-offer-149-v2';", 
    "const key = 'elvarins-shipping-offer-149-v2';\n  promo.querySelector('[data-offer-continue]')?.addEventListener('click', () => promo.close());");
}

